def prior_before(read):
    import sys, types
    s = PRIOR_SPEC
    need(s is not None, 'prior_before_source_pending')
    ref = s['before_ref']
    raw, f9 = read(Path(ref['path']), limit=4194304)
    need(sha(raw) == ref['sha256'] and f9 == ref['stat'] and (f9[3:7] == [0, 989, 33056, 1]), 'historical_R4_candidate_fixed_fullraw_F9')
    order = s['service_order']
    previous = {n[:-3]: sys.modules.get(n[:-3]) for n in order}
    mods = {}
    try:
        for name in order:
            path = Path(s['Root']) / 'service' / name
            code, st = read(path, limit=2097152)
            pin = s['Root77']['service/' + name]
            need(sha(code) == pin['sha256'] and st == pin['F9'], 'original_R4_validator_closure')
            m = types.ModuleType(name[:-3])
            m.__file__ = str(path)
            sys.modules[name[:-3]] = m
            mods[name[:-3]] = m
            exec(compile(code, str(path), 'exec'), m.__dict__)
    finally:
        for n, old in previous.items():
            if old is None:
                sys.modules.pop(n, None)
            else:
                sys.modules[n] = old
    archive = strict(raw)
    policyraw, ps = read(Path(s['Root']) / 'prelaunch-policy.json', limit=2097152)
    p = mods['prelaunch_history'].policy(policyraw)
    oldcfg = strict(s['old_config_raw_utf8'])
    oldcfg.update(_config_sha256=p['config_sha256'], _manager_identity=p['manager_identity'], max_clock_skew_seconds=30)
    old = mods['prelaunch_legacy'].load(p)
    old['live_idle'] = mods['live_idle']
    value = mods['prelaunch_history'].validate(archive['observation'], policyraw, oldcfg, archive['observation']['PC_finished_at'], old)
    need(value == archive['candidate'] and value['state'] == 'PRELAUNCH_NOT_STARTED' and (value['CPU_success'] is value['image_imported'] is False), 'old_candidate_original_validator_no_refresh')
    p['_policy_sha256'] = sha(policyraw)
    mods['prelaunch_proof'].A_original(archive['A_scope'], p)
    return {'candidate_ref': ref, 'state': 'PRELAUNCH_NOT_STARTED', 'CPU_success': False, 'image_imported': False, 'historical_operation': s['operation'], 'historical_finished_at': archive['observation']['PC_finished_at']}

