def source_frames(error):
    frames = []
    tb = error.__traceback__
    while tb is not None and len(frames) < 32:
        code = tb.tb_frame.f_code
        filename = code.co_filename
        if type(filename) is str and filename.startswith(str(PC_ROOT) + '/'):
            frames.append({'path': filename[:512], 'function': code.co_name[:128], 'line': tb.tb_lineno})
        tb = tb.tb_next
    return frames

def source_reason(error):
    text = str(error)
    return text if type(error).__name__ == 'Refused' and text in SAFE_REASONS else 'hidden_nonliteral'

def classify_stopped_original(read, original):
    import sys, types
    s = PRIOR_SPEC
    module = types.ModuleType('strict_actual_stopped_classification')
    path = Path(s['Root']) / 'service/prelaunch_stop.py'
    code, f9 = read(path, limit=2097152)
    pin = s['Root77']['service/prelaunch_stop.py']
    need(sha(code) == pin['sha256'] and f9 == pin['F9'], 'actual_classification_source_fullF9')
    saved_contract = sys.modules.get('contract')
    held_contract = types.ModuleType('contract')
    held_contract.__dict__.update(globals())
    sys.modules['contract'] = held_contract
    try:
        exec(compile(code, str(path), 'exec'), module.__dict__)
    finally:
        if saved_contract is None:
            sys.modules.pop('contract', None)
        else:
            sys.modules['contract'] = saved_contract
    need(sha(original['raw_utf8'].encode()) == original['sha256'] and sha(original['journal_raw_utf8'].encode()) == original['journal_sha256'] and (original['unit'] == dict((x.split('=', 1) for x in original['raw_utf8'].splitlines()))), 'actual_normal_stopped_original_fullraw_SHA')
    kind = module.classify(original['raw_utf8'].encode(), original['journal_raw_utf8'].encode(), s['current_stopped_identity'], module.LOGGER_SHA)
    need(kind == original['classification'], 'actual_normal_same_strict_classification')
    return kind
ACTUAL_STOPPED_SPEC = None

